package com.hms.billing;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.*; import java.util.UUID;
@Entity @Table(name="subscription_invoices") public class SubscriptionInvoice { @Id private UUID id; @Column(nullable=false) private UUID tenantId; @Column(nullable=false,unique=true,length=80) private String invoiceNumber; @Column(nullable=false,length=80) private String planKey; @Column(nullable=false,precision=12,scale=2) private BigDecimal subtotal; @Column(nullable=false,precision=12,scale=2) private BigDecimal taxAmount; @Column(nullable=false,precision=12,scale=2) private BigDecimal totalAmount; @Column(nullable=false,length=3) private String currency; @Enumerated(EnumType.STRING) @Column(nullable=false,length=30) private InvoiceStatus status; @Column(nullable=false) private LocalDate issuedOn; @Column(nullable=false) private LocalDate dueOn; private LocalDate paidOn; @Column(length=500) private String failureReason; @Column(nullable=false) private OffsetDateTime createdAt; protected SubscriptionInvoice(){} public SubscriptionInvoice(UUID tenantId,CreateInvoiceRequest r){this.id=UUID.randomUUID();this.tenantId=tenantId;this.invoiceNumber=r.invoiceNumber().trim();this.planKey=r.planKey().trim();this.subtotal=r.subtotal();this.taxAmount=r.taxAmount();this.totalAmount=r.subtotal().add(r.taxAmount());this.currency=r.currency().trim().toUpperCase();this.status=InvoiceStatus.OPEN;this.issuedOn=r.issuedOn();this.dueOn=r.dueOn();this.createdAt=OffsetDateTime.now();} public UUID getId(){return id;} public UUID getTenantId(){return tenantId;} public String getInvoiceNumber(){return invoiceNumber;} public String getPlanKey(){return planKey;} public BigDecimal getSubtotal(){return subtotal;} public BigDecimal getTaxAmount(){return taxAmount;} public BigDecimal getTotalAmount(){return totalAmount;} public String getCurrency(){return currency;} public InvoiceStatus getStatus(){return status;} public LocalDate getIssuedOn(){return issuedOn;} public LocalDate getDueOn(){return dueOn;} public LocalDate getPaidOn(){return paidOn;} public String getFailureReason(){return failureReason;} public void markPaid(){status=InvoiceStatus.PAID;paidOn=LocalDate.now();failureReason=null;} public void markPastDue(String reason){status=InvoiceStatus.PAST_DUE;failureReason=reason;} public void voidInvoice(){status=InvoiceStatus.VOID;} }
